import type { Item, Killer, Perk, Survivor } from '../types'
import componentsJson from './components.json'
import editPerksJson from './editPerks.json'
import offeringsJson from './offerings.json'
import itemsJson from './items.json'
import killersJson from './killers.json'
import survivorsJson from './survivors.json'

// Generated by scripts/build_assets.py from the transcriptions in ./raw
export const survivors = survivorsJson as Survivor[]
export const killers = killersJson as Killer[]
export const items = itemsJson as Item[]
export const components = componentsJson

export const survivorById = new Map(survivors.map((s) => [s.id, s]))
export const killerById = new Map(killers.map((k) => [k.id, k]))

/**
 * Every perk card in the box, for the edit-perks mode. Most are printed on a character board as
 * well; 35 of them are only cards, and those are the ones the engine can't find on a board.
 */
export const editPerkCards = editPerksJson as (Perk & { id: string; side: PerkKind })[]
export const editPerkById = new Map(editPerkCards.map((p) => [p.id, p]))

/** The offering cards (p.19), five a side: name, flavour and rules in English and Thai, both pictures. */
export interface Offering {
  id: string
  side: 'survivor' | 'killer'
  name: string
  flavor: { en: string; th: string }
  text: { en: string; th: string }
  image: { en: string; th: string }
}
export const offerings = offeringsJson as Offering[]

/** Whose perk a perk card is: a survivor's or a killer's. */
export type PerkKind = 'survivor' | 'killer'

// The skill-check die texture is cropped into skill-1..6.webp in this face order (0 = skull).
const SKILL_IMAGE_FACES = [2, 4, 5, 1, 3, 0]

/** Image of a skill check die face 0–5. */
export function skillFaceImage(face: number): string {
  return components.skillDieFaces[SKILL_IMAGE_FACES.indexOf(face)]
}
